'use client';
import {AccountingPostingAction} from '@/components/accounting-posting-action';
import {useEffect,useState} from 'react';
import {hotelRpc,type Membership} from '@/lib/pilot';
import {accountingUsd,readAccountingSetup,readPostingPreview,type AccountingSetup,type PostingPreview,type SourceReconciliation} from '@/lib/accounting';
export function AccountingPostingReview({membership,source,onClose}:{membership:Membership;source:SourceReconciliation['entries'][number];onClose:()=>void}){
 const [setup,setSetup]=useState<AccountingSetup|null>(null),[period,setPeriod]=useState(''),[date,setDate]=useState(source.service_date),[preview,setPreview]=useState<PostingPreview|null>(null),[error,setError]=useState(''),[loading,setLoading]=useState(true);
 const {tenant_id,property_id,role}=membership;
 useEffect(()=>{let current=true;setSetup(null);setPreview(null);setError('');setLoading(true);if(role!=='owner'&&role!=='manager'){setLoading(false);return;}hotelRpc<unknown>('gl_setup',{p_tenant:tenant_id,p_property:property_id}).then(value=>{const parsed=readAccountingSetup(value,tenant_id,property_id);if(current)setSetup(parsed);}).catch(cause=>{if(current)setError(cause instanceof Error?cause.message:'Unable to load setup.');}).finally(()=>{if(current)setLoading(false);});return()=>{current=false;};},[tenant_id,property_id,role]);
 const mapping=setup?.current_mapping;
 useEffect(()=>{let current=true;setPreview(null);if(!mapping||!period||!date||!(role==='owner'||role==='manager')){if(setup)setLoading(false);return;}setLoading(true);setError('');const expected={tenant_id,property_id,reservation_id:source.reservation_id,service_date:source.service_date,...(source.adjustment_id?{adjustment_id:source.adjustment_id}:{}),mapping_id:mapping.mapping_id,period_id:period,posting_date:date};const params={p_tenant:tenant_id,p_property:property_id,p_mapping:mapping.mapping_id,p_period:period,p_posting_date:date,...(source.adjustment_id?{p_adjustment:source.adjustment_id}:{p_service_date:source.service_date,p_reservation:source.reservation_id})};hotelRpc<unknown>(source.adjustment_id?'preview_forward_journal':'preview_service_journal',params).then(value=>{const parsed=readPostingPreview(value,expected);if(current)setPreview(parsed);}).catch(cause=>{if(current)setError(cause instanceof Error?cause.message:'Unable to preview posting.');}).finally(()=>{if(current)setLoading(false);});return()=>{current=false;};},[tenant_id,property_id,role,setup,mapping,period,date,source.reservation_id,source.service_date,source.adjustment_id]);
 if(role!=='owner'&&role!=='manager')return <p>Posting review requires manager access.</p>;
 return <section className="card" aria-label="Posting review" aria-busy={loading}><h3>Review source posting</h3><button className="secondary" onClick={onClose}>Back to reconciliation</button>{setup&&!mapping&&<p>Configure posting mappings before reviewing this source.</p>}<label className="field">Accounting period<select value={period} onChange={e=>{setPreview(null);setPeriod(e.target.value);}}><option value="">Select an open period</option>{setup?.periods.filter(p=>!p.closed).map(p=><option value={p.period_id} key={p.period_id}>{p.start_date} through {p.end_date_exclusive} (end excluded)</option>)}</select></label><label className="field">Posting date<input type="date" value={date} onChange={e=>{setPreview(null);setDate(e.target.value);}}/></label>{loading&&<p role="status">Loading posting review…</p>}{error&&<p role="alert" className="pilot-error">{error}</p>}{preview&&<><p>Mapping version {preview.mapping_version} · {preview.already_processed?'Already processed':'Not yet posted'}</p><div className="pilot-table-wrap"><table className="pilot-table"><caption>Proposed posting lines</caption><thead><tr><th>Account</th><th>Component</th><th>Side</th><th>USD</th></tr></thead><tbody>{preview.lines.map((l,i)=><tr key={i}><td>{l.account_code} · {l.current_account_name}</td><td>{l.component}</td><td>{l.side}</td><td>{accountingUsd(l.amount_minor)}</td></tr>)}</tbody></table></div>{!preview.lines.length&&<p>No journal lines are required for this source.</p>}</>}<AccountingPostingAction membership={membership} preview={loading?null:preview}/></section>;
}
